import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { getCartFromLS } from '../../utils/getCartFromLS';
import { cartSliceState, SelectedPizzas } from './types';

const initialState: cartSliceState = getCartFromLS();

export const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addPizza(state, action: PayloadAction<SelectedPizzas>) {
      const findPizza = state.selectedPizzas.find(
        (obj) =>
          obj.id === action.payload.id &&
          obj.type === action.payload.type &&
          obj.size === action.payload.size,
      );

      if (findPizza) {
        findPizza.count++;
        state.totalPrice += findPizza.finalPrice;
      } else {
        state.selectedPizzas.push({
          ...action.payload,
          count: 1,
        });
        state.totalPrice += action.payload.finalPrice;
      }
    },
    plusItem(state, action: PayloadAction<SelectedPizzas>) {
      const findPizza = state.selectedPizzas.find(
        (obj) =>
          obj.id === action.payload.id &&
          obj.type === action.payload.type &&
          obj.size === action.payload.size,
      );
      if (findPizza) {
        findPizza.count++;
        state.totalPrice += findPizza.finalPrice;
      }
    },
    minusItem(state, action: PayloadAction<SelectedPizzas>) {
      const findPizza = state.selectedPizzas.find(
        (obj) =>
          obj.id === action.payload.id &&
          obj.type === action.payload.type &&
          obj.size === action.payload.size,
      );
      if (findPizza && findPizza.count > 0) {
        findPizza.count--;
        state.totalPrice -= findPizza.finalPrice;
      }
    },
    removePizza(state, action: PayloadAction<SelectedPizzas>) {
      const item = state.selectedPizzas.find(
        (obj) =>
          obj.id === action.payload.id &&
          obj.type === action.payload.type &&
          obj.size === action.payload.size,
      );
      if (item) {
        state.totalPrice -= item.finalPrice * item.count;
      }

      state.selectedPizzas = state.selectedPizzas.filter(
        (obj) =>
          obj.id !== action.payload.id ||
          obj.type !== action.payload.type ||
          obj.size !== action.payload.size,
      );
    },
    clearSelectedPizzas(state) {
      state.selectedPizzas = [];
      state.totalPrice = 0;
    },
  },
});

export const { addPizza, plusItem, minusItem, removePizza, clearSelectedPizzas } =
  cartSlice.actions;

export default cartSlice.reducer;
