import { useSelector } from 'react-redux';
import { sizeImagesThinUrl, sizeImagesTraditionalUrl } from '../GlobalStyle';
import { selectPizzaData } from '../../redux/pizza/selectors';


interface ImgInModalProps {
  sizesTraditional: sizeImagesTraditionalUrl;
  sizesThin: sizeImagesThinUrl;
}

export const ImgInModal: React.FC<ImgInModalProps> = ({ sizesTraditional, sizesThin }) => {
  const { selectedDough, selectedSize } = useSelector(selectPizzaData);
  const sizeImagesTraditional = [
    sizesTraditional.modalUrl20cmTraditional,
    sizesTraditional.modalUrl25cmTraditional,
    sizesTraditional.modalUrl30cmTraditional,
    sizesTraditional.modalUrl35cmTraditional,
  ];

  const sizeImagesThin = [
    '',
    sizesThin.modalUrl25cmThin,
    sizesThin.modalUrl30cmThin,
    sizesThin.modalUrl35cmThin,
  ];
  const sizeClasses = ['cm-20', 'cm-25', 'cm-30', 'cm-35'];
  return (
    <>
      <img
        src={
          selectedDough === 0 ? sizeImagesTraditional[selectedSize] : sizeImagesThin[selectedSize]
        }
        alt="Пицца"
        className={sizeClasses[selectedSize]}
      />
    </>
  );
};

