import {SelectDough, SelectSize, ImgInModal} from '../../components';

import styles from './Modal.module.scss';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate, useParams, useSearchParams } from 'react-router';
import { sizeImagesThinUrl, sizeImagesTraditionalUrl } from '../GlobalStyle';
import { selectPizzaData } from '../../redux/pizza/selectors';
import { setSelectedDough, setSelectedSize } from '../../redux/pizza/slice';
import { addPizza } from '../../redux/cart/slice';

type ModalBuyPizzaProps = {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  sizesTraditional: sizeImagesTraditionalUrl;
  sizesThin: sizeImagesThinUrl;
  weightTraditionalBumpers: string[];
  id: number;
  imgUrl: string;
  price: number[];
};

const SizesDescription = ['20 см', '25 см', '30 см', '35 см'];
const DoughDescription = ['традиционное тесто', 'тонкое тесто'];

export const ModalBuyPizza: React.FC<ModalBuyPizzaProps> = ({
  isOpen,
  onClose,
  title,
  sizesTraditional,
  sizesThin,
  weightTraditionalBumpers,
  id,
  imgUrl,
  price,
}) => {
  const navigate = useNavigate();
  const { engTitle } = useParams();
  const [searchParams] = useSearchParams();
  const { selectedDough, selectedSize } = useSelector(selectPizzaData);
  const dispatch = useDispatch();
  if (!isOpen || !price || !weightTraditionalBumpers) return null;

  const finalPrice = price[selectedSize] ?? 0;
  const weight = weightTraditionalBumpers?.[selectedSize] ?? '';

  const changeDough = (doughIndex: number) => {
    dispatch(setSelectedDough(doughIndex));

    const newParams = new URLSearchParams(searchParams);
    newParams.set('dough', doughIndex === 1 ? 'thin' : 'traditional');
    newParams.set('size', ['20', '25', '30', '35'][selectedSize]);
    navigate(`/pizza/${engTitle}?${newParams.toString()}`);
  };

  const changeSize = (sizeIndex: number) => {
    dispatch(setSelectedSize(sizeIndex));
    const newParams = new URLSearchParams(searchParams);
    newParams.set('size', ['20', '25', '30', '35'][sizeIndex]);
    newParams.set('dough', selectedDough === 1 ? 'thin' : 'traditional');
    navigate(`/pizza/${engTitle}?${newParams.toString()}`);
  };
  const onClickAddPizza = () => {
    const selectedPizzas = {
      id,
      title,
      imgUrl,
      finalPrice,
      type: DoughDescription[selectedDough],
      size: SizesDescription[selectedSize],
      count: 0,
    };
    dispatch(addPizza(selectedPizzas));
    onClose();
  };
  return (
    <div
      className="modal"
      onClick={(e) => {
        if (e.target === e.currentTarget) {
          onClose();
        }
      }}
    >
      <div className="window" onClick={(e) => e.stopPropagation()}>
        <div className="pizzaWindow">
          <ImgInModal sizesTraditional={sizesTraditional} sizesThin={sizesThin} />
        </div>
        <div className="rightWindow">
          <div className="modalTitle">
            <h2>{title}</h2>
            <p>
              {SizesDescription[selectedSize] ?? ''}, {DoughDescription[selectedDough] ?? ''},{' '}
              {weight}
            </p>
          </div>
          <SelectDough onChangeDough={changeDough} />
          <SelectSize onChangeSize={changeSize} onChangeDough={changeDough} />
          <button className={styles.addButton} onClick={onClickAddPizza}>
            В корзину за {finalPrice}
          </button>
        </div>
      </div>
      <div
        onClick={(e) => {
          if (e.target !== e.currentTarget) {
            onClose();
          }
        }}
        className={styles.container}
      >
        <div className={styles.container}>
          <button className={styles.button}>
            <span className={`${styles.bar} ${styles.left}`}>
              <span className={`${styles.circle} ${styles.circleLeft}`}></span>
              <span className={`${styles.circle} ${styles.circleRight}`}></span>
            </span>
            <span className={`${styles.bar} ${styles.right}`}>
              <span className={`${styles.circle} ${styles.circleLeft}`}></span>
              <span className={`${styles.circle} ${styles.circleRight}`}></span>
            </span>
          </button>
        </div>
      </div>
    </div>
  );
};
