import { useSelector } from 'react-redux';
import { selectPizzaData } from '../../redux/pizza/selectors';

type SelectSizeProps = {
  onChangeSize: (index: number) => void;
  onChangeDough: (index: number) => void;
};

export const SelectSize: React.FC<SelectSizeProps> = ({ onChangeSize, onChangeDough }) => {
  const { selectedDough, selectedSize } = useSelector(selectPizzaData);
  const sizeType = ['20 см', '25 см', '30 см', '35 см'];

  const handleSelectedSize = (index: number) => {
    const is20 = index === 0;

    if (is20 && selectedDough === 1) {
      onChangeSize(0);
      onChangeDough(0);
      return;
    }

    onChangeSize(index);
  };
  return (
    <div style={{ margin: '10px' }}>
      <ul className="choice">
        <div
          className="active-slide"
          style={{
            transform: `translateX(${selectedSize * 100}%)`,
            width: `${100 / sizeType.length}%`,
          }}
        />
        {sizeType.map((name, index) => (
          <li key={index}>
            <input
              type="radio"
              name="SizeGroup"
              id={'size-tab-' + index}
              checked={selectedSize === index}
              onChange={() => handleSelectedSize(index)}
              style={{ display: 'none' }}
            />
            <label htmlFor={'size-tab-' + index}>{name}</label>
          </li>
        ))}
      </ul>
    </div>
  );
};
