import { createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";
import { PizzaObj } from "../../components/GlobalStyle";

export const fetchPizzas = createAsyncThunk('pizza/fetchPizzas', async () => {
  const { data } = await axios.get<PizzaObj[]>(
    `https://69a6ce5a2cd1d055268ef48e.mockapi.io/api/v1/items`,
  );
  return { data };
});