import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { pizzaSliceState, Status } from './types';
import { fetchPizzas } from './acyncActions';

const initialState: pizzaSliceState = {
  items: [],
  status: Status.IDLE,
  pages: 1,
  selectedDough: 0,
  selectedSize: 0,
};

export const pizzaSlice = createSlice({
  name: 'pizza',
  initialState,
  reducers: {
    setSelectedDough(state, action: PayloadAction<number>) {
      state.selectedDough = action.payload;
    },
    setSelectedSize(state, action: PayloadAction<number>) {
      state.selectedSize = action.payload;
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchPizzas.pending, (state) => {
        state.items = [];
        state.status = Status.LOADING;
      })
      .addCase(fetchPizzas.fulfilled, (state, action) => {
        state.items = action.payload.data;
        state.status = Status.SUCCESS;
      })
      .addCase(fetchPizzas.rejected, (state) => {
        state.items = [];
        state.status = Status.ERROR;
      });
  },
});

export const { setSelectedDough, setSelectedSize } = pizzaSlice.actions;
export default pizzaSlice.reducer;
