import ContentLoader from 'react-content-loader';

export const Skeleton = () => (
  <ContentLoader
    className="pizza-block"
    speed={2}
    width={280}
    height={480}
    viewBox="0 0 280 480"
    backgroundColor="#f3f3f3"
    foregroundColor="#ecebeb"
  >
    <circle cx="151" cy="147" r="130" /> 
    <rect x="0" y="436" rx="15" ry="15" width="87" height="32" /> 
    <rect x="170" y="436" rx="20" ry="20" width="105" height="38" /> 
    <rect x="0" y="356" rx="15" ry="15" width="280" height="50" /> 
    <rect x="0" y="303" rx="15" ry="15" width="280" height="32" />
  </ContentLoader>
);


