type PizzaBlockProps = {
  title: string;
  price: number[];
  description: string;
  imgUrl: string;
  onOpenModal: () => void;
};

export const PizzaBlock: React.FC<PizzaBlockProps> = ({
  title,
  price,
  description,
  imgUrl,
  onOpenModal,
}) => {
  return (
    <div className="pizza-block-wrapper">
      <div className="pizza-block" onClick={onOpenModal}>
        <img className="pizza-block__image" src={imgUrl} alt="Pizza" />
        <h4 className="pizza-block__title">{title}</h4>
        <div className="pizza-block__description">{description}</div>
        <div className="pizza-block__bottom">
          <div className="pizza-block__price">от {price[0]} ₽</div>
          <button className="button button--outline button--add">
            <span>Выбрать</span>
          </button>
        </div>
      </div>
    </div>
  );
};

